insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('37bff0df-2454-418b-b50a-db2845245a4e', 'es', '¿Por qué centrarte en disfrutar mejora los resultados al coquetear?', '["Elimina las intenciones ocultas", "Te hace estar más presente y relajado", "Hace que no dependas del resultado", "Prioriza demostrar lo que vales"]'::jsonb, 'Disfrutar redefine el éxito como el momento en sí, no como el resultado.')
