insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('90e66462-8fdd-4fa4-a574-bda55becad8c', 'es', '¿Cómo sabes si debes seguir coqueteando?', '["Confiar en tu intuición sobre la vibra de la interacción", "Fijarte en cómo responde ella, no en cómo te sientes tú", "Esperar a que diga claramente con palabras que le interesas", "Valorar si la conversación ya duró lo suficiente"]'::jsonb, 'Fíjate en sus respuestas y en cuánto se implica, no en cómo te sientes tú.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('eee49a49-b918-4f25-9827-edc1a9f9bdc0', 'es', '¿Qué señales sugieren que te contengas en lugar de avanzar?', '["Un tono neutro", "Respuestas cortas", "No te devuelve preguntas", "Una risa genuina"]'::jsonb, 'Si no te devuelve la energía, la interacción todavía no se ha abierto.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1ae2493f-bf71-457d-8f09-996e6cf2b464', 'es', '¿Qué significa el respeto al coquetear?', '["Valorar su comodidad y sus límites por encima de tu resultado", "Mostrar seguridad durante toda la interacción", "Tratarla como a una igual sin ser demasiado agresivo"]'::jsonb, 'El coqueteo se mantiene respetuoso cuando valoras su comodidad más que tu éxito.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('df3d8e11-15af-468e-ba4a-9cca550456d2', 'es', '¿Cuál es la forma más limpia de proteger a los dos cuando el interés no es mutuo?', '["Despedirte pronto y con educación", "Bromear para suavizar el momento", "Insistir un poco para confirmarlo", "Esperar a que ella te diga que no directamente"]'::jsonb, 'Despedirte pronto y con respeto mantiene el momento ligero y evita la incomodidad para los dos.')
