insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fed7fe50-0325-493e-8647-62755e05fab5', 'es', '¿Cuáles son los comportamientos mínimos de respeto?', '["Leer sus señales y respetarlas", "Aceptar el rechazo sin hacerla sentir culpable y sin mala actitud", "Nunca tocarla sin señales claras de que está cómoda", "Intentarlo una vez más si crees que puede ser tímida"]'::jsonb, 'El coqueteo se mantiene respetuoso cuando valoras su comodidad más que tu éxito.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('999e00ac-a18d-4b94-b3a8-e5c97c457f07', 'es', '¿Por qué la buena energía importa más que las frases?', '["La gente recuerda las sensaciones más que el contenido", "La atracción es sobre todo visual", "Las palabras están sobrevaloradas al coquetear", "La seguridad reemplaza a la conversación"]'::jsonb, 'Lo que se queda es la experiencia emocional. Las palabras importan menos que cómo se siente el momento.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a3ec5acd-f47b-4bb8-bf22-81d9b16edd73', 'es', 'Un grupo relajado está conversando con calma. ¿Cómo debería mostrarse tu energía?', '["Con mucha energía para destacar", "Un poco más relajada que la de ellos", "Igual a su ritmo o un poco por encima", "Callada y reservada"]'::jsonb, 'Acompañar su tono mantiene un ambiente cómodo y compartido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50f09b6c-abae-46f2-a825-8acf3d58107e', 'es', '¿Qué genera la buena energía?', '["Hace que la gente se sienta más ligera y más viva", "Los invita a abrirse y a jugar", "Demuestra seguridad social y carisma", "Crea el ambiente que hace posible el coqueteo"]'::jsonb, 'La buena energía crea seguridad y ganas de jugar, y eso permite que el coqueteo surja de forma natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a8695e9b-bb41-43c3-bf69-51511a2d5917', 'es', 'Te dice que le encanta el yoga y que es muy flexible. ¿Cómo puedes usar el humor?', '["Enumerar en serio los beneficios del yoga para la salud", "Contarle tu rutina de yoga en serio", "Preguntarle cuánto tiempo lleva practicando", "Preguntarle en broma si llega a tocarse los pies"]'::jsonb, 'Tomarle un poco el pelo crea una energía juguetona e invita al ida y vuelta con humor.')
