insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8150d416-c806-4f77-898e-1532d0bc733f', 'es', '¿Qué deberías evitar al tomarle el pelo?', '["Exagerar algo de lo que parece estar orgullosa", "Un ida y vuelta desenfadado", "Retarla en broma sobre lo que dijo", "Temas que puedan hacerla sentir insegura"]'::jsonb, 'Tomarle el pelo funciona cuando es divertido, no cuando puede herirla.')
