insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e5a0bc4-d01b-4f85-9404-749642fa56b6', 'es', '¿Cuáles son ejemplos de temas seguros para tomarle el pelo?', '["Su aspecto físico", "Que es muy competitiva", "Que es demasiado organizada", "Que cocina muy mal"]'::jsonb, 'Tómale el pelo con rasgos ligeros, que no amenacen y que no estén ligados a inseguridades.')
