insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('63acae8c-e04a-4fc9-98cb-693c477cc5f0', 'es', '¿Qué hace eficaces los retos ligeros y divertidos?', '["Le dan permiso para ser competitiva y mostrar su personalidad", "Gane quien gane, hay un motivo para seguir la interacción", "Pasa de responder preguntas a jugar de verdad", "Todas las anteriores"]'::jsonb, 'Los retos ligeros invitan a jugar, muestran la personalidad y mantienen viva la interacción.')
