insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9ce27a06-8ab6-4d7f-9ede-e0cfb8108698', 'es', 'Te pregunta: “¿Cuántos años tienes?”. ¿Qué podrías decir como reto divertido?', '["Decirle tu edad exacta directamente", "Decirle que la edad no importa", "Ignorar la pregunta", "“¿Cuántos me echas? Adivina”"]'::jsonb, 'Conviértelo en un juego de adivinar para crear tensión compartida y un ida y vuelta con humor.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9e5d1aff-d472-4ad6-af85-3661a0c5fa0d', 'es', '¿Qué ejemplos de retos ligeros funcionan bien?', '["“A que no dices tres capitales más rápido que yo”", "“A que adivino qué sueles pedir de tomar”", "“¿Cuántos me echas? Adivina”", "“Piedra, papel o tijera por la siguiente ronda”"]'::jsonb, 'Un reto ligero es un juego compartido, no una prueba ni una presión. No hay nada real en juego.')
