insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('72b1b5eb-51d6-4bae-82e9-d9b516852a92', 'es', '¿Qué hace que la picardía funcione en vez de ofender?', '["La calidez al decirlo: la sonrisa deja claro que estás jugando", "El tono importa más que las palabras exactas", "Un enfoque ligero e inesperado, no cruel ni crítico", "Todas las anteriores"]'::jsonb, 'La picardía funciona cuando la calidez, el tono y la ligereza indican juego, no juicio.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c04e3fb3-07b8-49cb-9664-d35c6a113928', 'es', 'Te dice: “Siempre llego tarde”. ¿Qué podrías decir?', '["“Menos mal que yo soy muy paciente”", "“No pasa nada, nadie es perfecto.”", "“¿Por qué llegas tarde?”", "“Yo suelo ser puntual.”"]'::jsonb, 'Una respuesta pícara con una sonrisa la invita a seguirte el juego con ligereza.')
