insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('41b88925-4d87-4998-bcfb-64846e12bd89', 'es', '¿Por qué un poco de picardía ayuda al coquetear?', '["Rompe la dinámica de darle la razón en todo", "Muestra seguridad con calidez", "Crea tensión juguetona y ritmo", "Exige un desacuerdo serio"]'::jsonb, 'Llevarle un poco la contraria rompe la monotonía, crea tensión juguetona y mantiene viva la energía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('73e2048d-c6ed-4778-ac5a-699f953efb85', 'es', '¿Qué cumplido tiene más probabilidades de crear conexión?', '["“Eres muy guapa.”", "“Tienes unos ojos increíbles.”", "“Seguro que te hacen cumplidos todo el tiempo.”", "“Me gusta cómo explicas las cosas.”"]'::jsonb, 'Los cumplidos llegan mejor cuando reflejan lo que ella elige hacer, no sus rasgos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3cb92c32-a188-4032-9345-29df03006c3e', 'es', 'Te da un punto de vista interesante. ¿Qué es un buen cumplido?', '["“Qué forma tan original de verlo.”", "“Eres muy inteligente.”", "“No eres como las demás.”", "“Me gusta tu acento.”"]'::jsonb, 'Reconocer su perspectiva se siente cálido y sin presión.')
