insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('30a03b40-5f82-4a6d-9f66-d9ad8a4b99b5', 'es', '¿Qué cumplidos tienen más probabilidades de caer bien?', '["“Tienes una energía muy bonita cuando hablas de esto.”", "“Estás buenísima.”", "“Me gusta lo curiosa que eres con este tema.”", "“Estás fuera de mi alcance.”"]'::jsonb, 'Los mejores cumplidos son los que reconocen su forma de actuar, su energía o su carácter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1172a812-9aff-4cbd-a84b-c14454c9e1fa', 'es', '¿Qué hace que un cumplido sea coqueto y no solo amable?', '["Decirlo rápido y en tono casual", "Un ritmo pausado y una voz más cálida", "Sostener la mirada y dejar que llegue", "Palabras concretas sobre su aspecto"]'::jsonb, 'El tono, el momento y la presencia crean la señal romántica, no solo el contenido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9557570b-b2cb-4bd4-bb90-12db51a495fc', 'es', '¿Cómo puedes decir un cumplido para que genere atracción y no solo cortesía?', '["Sosteniendo la mirada con una pequeña sonrisa", "Con una voz más cálida y pausada", "Dejando una pausa después del cumplido", "Todas las anteriores"]'::jsonb, 'La intención que pones en el tono y el momento transmite deseo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f5fab3d7-5d70-4bb8-82fa-cb750e038f03', 'es', 'Con las mismas palabras, ¿qué versión tiene más probabilidades de crear tensión romántica?', '["“Me gusta tu vestido”, dicho rápido al pasar", "“Me gusta tu vestido”, dicho sosteniendo la mirada y con una pausa tranquila", "“Me gusta tu vestido”, dicho desde detrás de ella"]'::jsonb, 'La calidez sumada a tu presencia hace que se sienta intencional y no algo dicho por decir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('92141af3-4469-4cb2-aeca-c8b66beca062', 'es', '¿Qué permite que una sola frase lleve una interacción de lo cortés a lo coqueto?', '["Decir explícitamente tu intención romántica para que no haya ambigüedad", "Dejar ver tu interés de forma sutil, sin comprometerte del todo", "Hacer un cumplido más fuerte que antes para aumentar la atracción"]'::jsonb, 'Un giro coqueto funciona mejor cuando insinúa el interés en lugar de declararlo directamente.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d81d87c2-562a-4457-9339-626b9b62911d', 'es', 'La charla fluye con facilidad y ella se inclina un poco hacia ti. ¿Qué frase sutil podría cambiar el tono?', '["“Eres interesante.”", "“Hablamos bien.”", "“Me gusta cómo se siente esta conversación contigo.”"]'::jsonb, 'Nombra con suavidad la vibra que ya existe y abre espacio para el coqueteo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('de314e72-aecd-48e2-9e7e-904002814fcb', 'es', '¿Qué frases sirven para cambiar el ambiente?', '["“Vamos a tomar un café algún día”", "“Me gusta cómo se siente esta conversación contigo.”", "“No esperaba conocer a alguien como tú hoy”", "“Deberíamos repetir esto algún día”"]'::jsonb, 'Un giro coqueto funciona mejor cuando insinúa el interés en lugar de declararlo directamente.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bc3c84b8-fcbd-4347-ba4e-29499525a333', 'es', '¿Por qué apartar la mirada demasiado rápido debilita la atracción?', '["Transmite nervios o inseguridad", "Parece de mala educación", "Confunde la conversación", "Le quita claridad a lo que dices"]'::jsonb, 'Apartar la mirada una y otra vez rompe la tensión y frena el avance.')
