insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('63f473ff-9a6a-4125-9a7b-03d7c4df9882', 'es', '¿Por qué el contacto visual puede cambiar una conversación mejor que un cumplido?', '["Se siente menos ensayado", "Se salta la lógica y actúa sobre lo que se siente", "Reduce la necesidad de palabras", "Todas las anteriores"]'::jsonb, 'El contacto visual actúa en lo emocional y lo instintivo, no en lo intelectual.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7dd24452-9d73-4619-a644-95a9de2edd1d', 'es', '¿Qué momentos son los más adecuados para sostener la mirada?', '["Durante las pausas naturales", "Cuando ella habla con emoción", "Mientras la interrumpes", "Cuando la conversación se calma un momento"]'::jsonb, 'El contacto visual funciona mejor en momentos tranquilos y compartidos, no cuando interrumpes.')
