insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79c89303-fe65-481b-8506-11cd45eaed32', 'es', 'La vibra es buena, pero te quedas lejos de ella. ¿Qué riesgo corres?', '["Parecer demasiado interesado", "Incomodarla", "Transmitir desinterés aunque tus palabras digan otra cosa", "Ir demasiado rápido"]'::jsonb, 'Una distancia que no encaja puede restarle fuerza a tu interés expresado con palabras.')
