insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f7200ef5-2102-4d79-abd9-e518cc3c8af8', 'es', 'Das un pequeño paso hacia ella y ella da un paso atrás discretamente. ¿Qué significa?', '["Necesita más espacio en este momento", "Quiere que insistas con seguridad", "Te está poniendo a prueba", "No le gustas para nada"]'::jsonb, 'Un paso atrás es información, no un rechazo. Dale espacio y vuelve a ajustarte.')
