insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a9930259-a42a-49fb-bdd4-9d319fe4fd04', 'es', '¿Qué errores generan incomodidad con la cercanía?', '["Acercarte antes de que haya complicidad", "Ignorar sus reacciones físicas", "Ajustar la distancia poco a poco", "Quedarte rígido aunque ella se incline hacia ti"]'::jsonb, 'La incomodidad viene de ignorar sus reacciones o de no responder a ellas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c56a1006-a63d-4532-801e-49829be4ccd2', 'es', '¿Qué ayuda a comunicar el efecto espejo con el cuerpo?', '["Atracción mediante la imitación", "Dominancia y control", "Seguridad social y comodidad", "Seguridad en ti mismo a través de la postura"]'::jsonb, 'Reflejar su postura transmite familiaridad y comodidad a nivel inconsciente, y eso favorece la complicidad.')
