insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a5612de-f9a6-4bc1-bcbb-29d29d0b1f91', 'es', 'Ella habla bajito y despacio durante la conversación. ¿Qué deberías igualar?', '["Subir el volumen para darle energía", "Seguir con tu tono fuerte de antes", "Hablar rápido para mantener el ritmo", "Bajar la voz y hablar más pausado"]'::jsonb, 'Igualar su energía y su tono crea complicidad de forma inconsciente.')
